package me.minis.ledger;
import android.content.*;import android.os.*;import org.json.*;import java.util.*;
/** Event-driven diagnostics, never stores notification text, amounts or UI content. */
public final class PowerDetail {
 private static Context app;private static boolean active=false,front=false;private static long since=0,lastFlush=0,lastPoint=0,fgCpu=0,bgCpu=0,fgTime=0,bgTime=0,peakHeap=0;
 private static final LinkedHashMap<String,long[]> metrics=new LinkedHashMap<>();private static JSONArray timeline=new JSONArray();private static final LinkedHashMap<String,Long> sources=new LinkedHashMap<>();
 public static synchronized void init(Context c){app=c.getApplicationContext();active=LedgerDb.prefs(app).getBoolean("probe_on",false);try{JSONObject j=new JSONObject(LedgerDb.prefs(app).getString("probe_detail","{}"));since=j.optLong("since",System.currentTimeMillis());fgCpu=j.optLong("fgCpu");bgCpu=j.optLong("bgCpu");fgTime=j.optLong("fgTime");bgTime=j.optLong("bgTime");peakHeap=j.optLong("peakHeap");JSONObject m=j.optJSONObject("metrics");if(m!=null){Iterator<String> keys=m.keys();while(keys.hasNext()){String k=keys.next();JSONArray v=m.getJSONArray(k);long[] b=new long[5];for(int i=0;i<5;i++)b[i]=v.optLong(i);metrics.put(k,b);}}JSONObject s=j.optJSONObject("sources");if(s!=null){Iterator<String> keys=s.keys();while(keys.hasNext()){String k=keys.next();if(sources.size()<24)sources.put(k,s.optLong(k));}}JSONArray t=j.optJSONArray("timeline");if(t!=null){timeline=t;if(t.length()>0)lastPoint=t.getJSONObject(t.length()-1).optLong("time");}}catch(Exception ignored){since=System.currentTimeMillis();}if(active&&since==0)since=System.currentTimeMillis();}
 public static synchronized void reset(){metrics.clear();sources.clear();timeline=new JSONArray();fgCpu=bgCpu=fgTime=bgTime=peakHeap=0;since=System.currentTimeMillis();lastFlush=lastPoint=0;active=true;persist(true);}
 public static synchronized void stop(){persist(true);active=false;}
 public static synchronized void front(boolean value){front=value;count(value?"resume":"pause");persist(true);}
 public static synchronized void count(String key){if(!active)return;long[] b=metrics.get(key);if(b==null){if(metrics.size()>=48)return;b=new long[5];metrics.put(key,b);}b[0]++;}
 public static synchronized void source(String pkg){if(!active||pkg==null)return;if(!sources.containsKey(pkg)&&sources.size()>=24)pkg="other";sources.put(pkg,sources.containsKey(pkg)?sources.get(pkg)+1:1L);}
 public static void webRender(long ms){add("web_callback",0,Math.max(0,ms));}
 public static synchronized void delay(long ms){if(!active)return;long[] b=metrics.get("queue");if(b==null){b=new long[5];metrics.put("queue",b);}b[0]++;b[2]+=Math.max(0,ms);b[3]=Math.max(b[3],ms);}
 public static final class Span implements AutoCloseable {private final String key;private final long wall,cpu;private Span(String k){key=k;wall=SystemClock.elapsedRealtime();cpu=SystemClock.currentThreadTimeMillis();}public void close(){add(key,Math.max(0,SystemClock.currentThreadTimeMillis()-cpu),Math.max(0,SystemClock.elapsedRealtime()-wall));}}
 public static Span span(String key){synchronized(PowerDetail.class){return active?new Span(key):null;}}
 private static synchronized void add(String key,long cpu,long wall){if(!active)return;long[] b=metrics.get(key);if(b==null){if(metrics.size()>=48)return;b=new long[5];metrics.put(key,b);}b[0]++;b[1]+=cpu;b[2]+=wall;b[3]=Math.max(b[3],wall);if(wall>=100)b[4]++;}
 public static synchronized void sample(long cpu,long elapsed,int level){if(!active)return;if(front){fgCpu+=cpu;fgTime+=elapsed;}else{bgCpu+=cpu;bgTime+=elapsed;}Runtime r=Runtime.getRuntime();peakHeap=Math.max(peakHeap,r.totalMemory()-r.freeMemory());long now=System.currentTimeMillis();if(now-lastPoint>=300000){try{JSONObject p=new JSONObject();p.put("time",now);p.put("cpu",fgCpu+bgCpu);p.put("front",front);p.put("heap",r.totalMemory()-r.freeMemory());p.put("level",level);JSONArray next=new JSONArray();for(int i=Math.max(0,timeline.length()-47);i<timeline.length();i++)next.put(timeline.get(i));next.put(p);timeline=next;lastPoint=now;}catch(Exception ignored){}}persist(false);}
 public static synchronized JSONObject state(){JSONObject j=new JSONObject();try{j.put("since",since);j.put("fgCpu",fgCpu);j.put("bgCpu",bgCpu);j.put("fgTime",fgTime);j.put("bgTime",bgTime);j.put("peakHeap",peakHeap);JSONObject m=new JSONObject();for(Map.Entry<String,long[]> e:metrics.entrySet())m.put(e.getKey(),new JSONArray(e.getValue()));j.put("metrics",m);j.put("sources",new JSONObject(sources));j.put("timeline",timeline);j.put("pid",android.os.Process.myPid());j.put("javaHeap",Runtime.getRuntime().totalMemory()-Runtime.getRuntime().freeMemory());j.put("nativeHeap",Debug.getNativeHeapAllocatedSize());j.put("note","分项为同线程CPU/墙钟耗时，父子阶段可重叠，不可相加成总耗电。主进程CPU不含WebView隔离进程。时间线至少5分钟间隔且仅随事件采样；整机电量非App归因。未观测时段不补造数据。");}catch(Exception ignored){}return j;}
 private static void persist(boolean force){if(app==null||!active)return;long now=SystemClock.elapsedRealtime();if(!force&&now-lastFlush<60000)return;lastFlush=now;count("detail_flush");LedgerDb.prefs(app).edit().putString("probe_detail",state().toString()).apply();}
 public static JSONObject report(Context c)throws Exception {synchronized(PowerDetail.class){persist(true);}JSONObject j=new JSONObject();j.put("app","轻记");j.put("version",c.getPackageManager().getPackageInfo(c.getPackageName(),0).versionName);j.put("exportedAt",System.currentTimeMillis());j.put("device",Build.MANUFACTURER+" "+Build.MODEL);j.put("android",Build.VERSION.RELEASE);j.put("probe",PowerProbe.state(c));j.put("detail",state());SharedPreferences p=LedgerDb.prefs(c);JSONObject options=new JSONObject();options.put("capture",p.getBoolean("capture",true));options.put("screenCapture",p.getBoolean("screen_capture",false));options.put("listenerConnected",PaymentListener.connected);options.put("summaryOn",p.getBoolean("summary_on",true));j.put("options",options);j.put("packageName",c.getPackageName());j.put("screenDiagnostics",PaymentScreenService.diagnostics());j.put("limits","独立App mAh/系统唤醒锁/完整UID与WebView耗电需要Android系统电池统计或ADB/Shizuku外部采集。本报告不申请特权、不估算App mAh、不读取通知原文。");return j;}
}
